/**
 * Film palettes (style bible §2). Every mood shares one CIELAB lightness
 * ladder; only hue/chroma change. Values come from palettes.json, generated by
 * tools/film/palette.mjs — regenerate rather than hand-edit.
 *
 *   mood('duskRose')                       -> Palette
 *   crossfadeMood('labGreen','winterBlue', u)  -> Palette (Lab interpolation, every token)
 *   mixLab(a, b, u)                        -> hex
 *   hazed(palette, role, haze)             -> the fill for a role at a layer's haze amount
 *   makeEnv({ mood, layer, t, ... })       -> a PaintEnv (galleries, tests, core Frame)
 */
import { interpolateLab, color } from 'd3';
import type { FillRole, LayerSpec, MoodId, Palette, PaintEnv } from '../contracts';
import { LAYERS, quantizeTwos } from '../contracts';
import RAW from './palettes.json';

type RawPalette = Omit<Palette, 'id' | 'horizon' | 'sky'> & { sky: string[] };

const HORIZON: Partial<Record<MoodId, number>> = { parchment: 0.5 };

export const MOODS: Record<MoodId, Palette> = Object.fromEntries(
  Object.entries(RAW as Record<string, RawPalette>).map(([id, p]) => [
    id,
    { ...p, id, sky: p.sky as Palette['sky'], horizon: HORIZON[id as MoodId] ?? 0.6 },
  ]),
) as Record<MoodId, Palette>;

export const MOOD_IDS = Object.keys(MOODS) as MoodId[];

export function mood(m: MoodId | Palette): Palette {
  if (typeof m !== 'string') return m;
  const p = MOODS[m];
  if (!p) throw new Error(`unknown mood "${m}" (have ${MOOD_IDS.join(', ')})`);
  return p;
}

const lerpCache = new Map<string, (u: number) => string>();
/** Lab interpolation between two colours, returned as #rrggbb. */
export function mixLab(a: string, b: string, u: number): string {
  if (u <= 0) return a;
  if (u >= 1) return b;
  const key = a + b;
  let f = lerpCache.get(key);
  if (!f) {
    f = interpolateLab(a, b);
    lerpCache.set(key, f);
  }
  return color(f(u))!.formatHex();
}

/** Crossfade every token of two moods in Lab (style bible: 1.5–3 s between sequences). */
export function crossfadeMood(a: MoodId | Palette, b: MoodId | Palette, u: number): Palette {
  const A = mood(a);
  const B = mood(b);
  if (u <= 0) return A;
  if (u >= 1) return B;
  const m = (k: keyof Omit<Palette, 'id' | 'sky' | 'horizon'>) => mixLab(A[k], B[k], u);
  return {
    id: `${A.id}->${B.id}@${u.toFixed(3)}`,
    sky: [0, 1, 2, 3].map((i) => mixLab(A.sky[i], B.sky[i], u)) as Palette['sky'],
    set: m('set'),
    setHaze: m('setHaze'),
    haze: m('haze'),
    fg: m('fg'),
    ink: m('ink'),
    rim: m('rim'),
    halo: m('halo'),
    core: m('core'),
    horizon: A.horizon + (B.horizon - A.horizon) * u,
  };
}

/**
 * The fill for a semantic role on a layer with haze h (style bible §2.4):
 * architecture mixes set→haze, figures/props mix ink→haze, frame occluders stay fg.
 * Lights (rim/halo/core) are never hazed.
 */
export function hazed(p: Palette, role: FillRole, h: number): string {
  switch (role) {
    case 'ink':
      return mixLab(p.ink, p.haze, h);
    case 'set':
      return mixLab(p.set, p.haze, h);
    case 'fg':
      return h > 0 ? mixLab(p.fg, p.haze, h * 0.5) : p.fg;
    case 'haze':
      return p.haze;
    default:
      return p[role];
  }
}

/** Build a PaintEnv by hand (galleries/tests). The core Frame builds the same object per layer. */
export function makeEnv(o: {
  mood: MoodId | Palette;
  layer?: LayerSpec | keyof typeof LAYERS;
  t?: number;
  fps?: number;
  pxScale?: number;
  seed?: number;
  frame?: number;
}): PaintEnv {
  const p = mood(o.mood);
  const layer = typeof o.layer === 'string' ? LAYERS[o.layer] : o.layer ?? LAYERS.L4;
  const t = o.t ?? 0;
  const fps = o.fps ?? 24;
  return {
    mood: p,
    fill: (role) => hazed(p, role, layer.haze),
    layer,
    t,
    tq: quantizeTwos(t),
    frame: o.frame ?? Math.round(t * fps),
    fps,
    pxScale: o.pxScale ?? 1.5,
    seed: o.seed ?? 1,
  };
}

/** rgba() string from a hex colour and alpha (for gradients/glows). */
export function withAlpha(hex: string, a: number): string {
  const c = color(hex)!.rgb();
  return `rgba(${Math.round(c.r)},${Math.round(c.g)},${Math.round(c.b)},${Math.max(0, Math.min(1, a))})`;
}
